#include "VoxelReflections.h"

/* Generated by FxCompile from Shaders\Voxel*.hlsl */
#include "Shaders/VoxelReflectionsDebug.h"
#include "Shaders/VoxelUpdate.h"
#include "Shaders/VoxelCarve.h"
#include "Shaders/VoxelInject.h"
#include "Shaders/VoxelTrace.h"






void VoxelReflections::SsrDraw::Release()
{
	for (ID3D11ShaderResourceView*& srv : srvs)
		Utilities::SafeRelease(srv);
	Utilities::SafeRelease(view);
	Utilities::SafeRelease(target);
}

namespace
{
	/* Texture2D description of the resource behind a view; optionally keeps a reference to the resource */
	bool Describe(ID3D11View* view, D3D11_TEXTURE2D_DESC& desc, ID3D11Resource** keep = nullptr)
	{
		if (view == nullptr)
			return false;
		ID3D11Resource* resource = nullptr;
		view->GetResource(&resource);
		if (resource == nullptr)
			return false;
		D3D11_RESOURCE_DIMENSION dimension = D3D11_RESOURCE_DIMENSION_UNKNOWN;
		resource->GetType(&dimension);
		const bool isTexture = dimension == D3D11_RESOURCE_DIMENSION_TEXTURE2D;
		if (isTexture)
			static_cast<ID3D11Texture2D*>(resource)->GetDesc(&desc);
		if (isTexture && keep)
			*keep = resource;
		else
			resource->Release();
		return isTexture;
	}

	bool IsRgba16(DXGI_FORMAT format)
	{
		return format == DXGI_FORMAT_R16G16B16A16_FLOAT || format == DXGI_FORMAT_R16G16B16A16_TYPELESS;
	}

	bool SameSize(const D3D11_TEXTURE2D_DESC& a, const D3D11_TEXTURE2D_DESC& b)
	{
		return a.Width == b.Width && a.Height == b.Height;
	}
}




/* Checks the bindings of the current draw against the SSR pass (see VoxelReflections.h) */
bool VoxelReflections::Match(ID3D11DeviceContext* context, SsrDraw& draw)
{
	ID3D11PixelShader* pixelShader = nullptr;
	context->PSGetShader(&pixelShader, nullptr, nullptr);
	void* shaderAddress = pixelShader;
	Utilities::SafeRelease(pixelShader);
	if (shaderAddress == nullptr || (ssrPixelShader && shaderAddress != ssrPixelShader))
		return false;

	UINT viewportCount = 1;
	context->RSGetViewports(&viewportCount, &draw.viewport);
	if (viewportCount == 0 || draw.viewport.Width < 64.0f || draw.viewport.Height < 64.0f)
		return false;

	/* One FP16 colour target, no depth buffer */
	ID3D11RenderTargetView* rtvs[2] = {};
	ID3D11DepthStencilView* dsv = nullptr;
	context->OMGetRenderTargets(2, rtvs, &dsv);
	D3D11_TEXTURE2D_DESC target = {};
	bool ok = rtvs[1] == nullptr && dsv == nullptr && Describe(rtvs[0], target, &draw.target) && IsRgba16(target.Format) &&
	          target.Width >= static_cast<UINT>(draw.viewport.TopLeftX + draw.viewport.Width) &&
	          target.Height >= static_cast<UINT>(draw.viewport.TopLeftY + draw.viewport.Height);
	for (ID3D11RenderTargetView*& rtv : rtvs)
		Utilities::SafeRelease(rtv);
	Utilities::SafeRelease(dsv);
	if (ok == false)
		return false;

	context->PSGetShaderResources(0, SLOT_COUNT, draw.srvs);

	D3D11_SHADER_RESOURCE_VIEW_DESC depthView = {};
	if (draw.srvs[SLOT_DEPTH])
		draw.srvs[SLOT_DEPTH]->GetDesc(&depthView);
	D3D11_TEXTURE2D_DESC depth = {}, gbufferA = {}, gbufferB = {}, sceneColor = {}, hzb = {};
	ID3D11Resource* sceneColorResource = nullptr;

	ok = Describe(draw.srvs[SLOT_DEPTH], depth) && SameSize(depth, target) &&
	     (depthView.Format == DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS || depthView.Format == DXGI_FORMAT_R24_UNORM_X8_TYPELESS ||
	      depthView.Format == DXGI_FORMAT_R32_FLOAT) &&
	     Describe(draw.srvs[SLOT_GBUFFER_A], gbufferA) && SameSize(gbufferA, target) &&
	     (gbufferA.Format == DXGI_FORMAT_R10G10B10A2_UNORM || gbufferA.Format == DXGI_FORMAT_R10G10B10A2_TYPELESS) &&
	     Describe(draw.srvs[SLOT_GBUFFER_B], gbufferB) && SameSize(gbufferB, target) &&
	     Describe(draw.srvs[SLOT_SCENE_COLOR], sceneColor, &sceneColorResource) && SameSize(sceneColor, target) && IsRgba16(sceneColor.Format) &&
	     sceneColorResource != draw.target &&
	     Describe(draw.srvs[SLOT_HZB], hzb) && hzb.MipLevels >= 4 &&
	     (hzb.Format == DXGI_FORMAT_R16_FLOAT || hzb.Format == DXGI_FORMAT_R16_TYPELESS || hzb.Format == DXGI_FORMAT_R32_FLOAT);
	Utilities::SafeRelease(sceneColorResource);
	if (ok == false)
		return false;

	/* The engine View uniform buffer: only needed by the voxel passes and the world grid, checked there */
	if (viewBufferSlot >= 0 && viewBufferSlot < static_cast<int32_t>(D3D11_COMMONSHADER_CONSTANT_BUFFER_API_SLOT_COUNT))
		context->PSGetConstantBuffers(static_cast<UINT>(viewBufferSlot), 1, &draw.view);

	draw.targetFormat = target.Format;
	draw.targetWidth = target.Width;
	draw.targetHeight = target.Height;
	draw.hzbWidth = hzb.Width;
	draw.hzbHeight = hzb.Height;
	draw.hzbMips = hzb.MipLevels;

	if (ssrPixelShader == nullptr)
	{
		ssrPixelShader = shaderAddress;
		Utilities::Log::Write("voxel reflections: SSR draw found (pixel shader %p, viewport %.0fx%.0f, target %ux%u, HZB %ux%u with %u mips)",
		                      shaderAddress, draw.viewport.Width, draw.viewport.Height, target.Width, target.Height, hzb.Width, hzb.Height,
		                      hzb.MipLevels);
	}
	return true;
}




bool VoxelReflections::Volume::Create(ID3D11Device* device, DXGI_FORMAT format)
{
	D3D11_TEXTURE3D_DESC desc = {};
	desc.Width = desc.Height = desc.Depth = RESOLUTION;
	desc.MipLevels = 1;
	desc.Format = format;
	desc.Usage = D3D11_USAGE_DEFAULT;
	desc.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
	if (FAILED(device->CreateTexture3D(&desc, nullptr, &texture)) || FAILED(device->CreateShaderResourceView(texture, nullptr, &srv)) ||
	    FAILED(device->CreateUnorderedAccessView(texture, nullptr, &uav)))
	{
		Release();
		return false;
	}
	return true;
}

void VoxelReflections::Volume::Release()
{
	Utilities::SafeRelease(uav);
	Utilities::SafeRelease(srv);
	Utilities::SafeRelease(texture);
}




bool VoxelReflections::Initialize(ID3D11Device* device)
{
	initTried = true;

	struct ShaderSource
	{
		const void* bytecode;
		size_t size;
		ID3D11ComputeShader** shader;
		const char* name;
	};
	const ShaderSource shaders[] =
	{
		{ g_VoxelReflectionsDebug, sizeof(g_VoxelReflectionsDebug), &debugShader, "debug" },
		{ g_VoxelUpdate, sizeof(g_VoxelUpdate), &updateShader, "update" },
		{ g_VoxelCarve, sizeof(g_VoxelCarve), &carveShader, "carve" },
		{ g_VoxelInject, sizeof(g_VoxelInject), &injectShader, "inject" },
		{ g_VoxelTrace, sizeof(g_VoxelTrace), &traceShader, "trace" },
	};
	for (const ShaderSource& source : shaders)
	{
		if (FAILED(device->CreateComputeShader(source.bytecode, source.size, nullptr, source.shader)))
		{
			Utilities::Log::Write("voxel reflections: failed to create the %s shader", source.name);
			return false;
		}
	}

	D3D11_BUFFER_DESC bufferDesc = {};
	bufferDesc.Usage = D3D11_USAGE_DYNAMIC;
	bufferDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
	bufferDesc.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
	bufferDesc.ByteWidth = sizeof(Constants);
	if (FAILED(device->CreateBuffer(&bufferDesc, nullptr, &constants)))
	{
		Utilities::Log::Write("voxel reflections: failed to create the constant buffer");
		return false;
	}

	D3D11_SAMPLER_DESC samplerDesc = {};
	samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
	samplerDesc.AddressU = samplerDesc.AddressV = samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;
	if (FAILED(device->CreateSamplerState(&samplerDesc, &linearWrap)))
	{
		Utilities::Log::Write("voxel reflections: failed to create the sampler");
		return false;
	}

	Utilities::Log::Write("voxel reflections: shaders ready");
	return true;
}

bool VoxelReflections::CreateVolumes(ID3D11Device* device)
{
	volumesTried = true;

	/* R11G11B10F halves the memory; every D3D11 GPU should store to it from compute, but check */
	UINT support = 0;
	const UINT needed = D3D11_FORMAT_SUPPORT_TEXTURE3D | D3D11_FORMAT_SUPPORT_SHADER_SAMPLE | D3D11_FORMAT_SUPPORT_TYPED_UNORDERED_ACCESS_VIEW;
	radianceFormat = SUCCEEDED(device->CheckFormatSupport(DXGI_FORMAT_R11G11B10_FLOAT, &support)) && (support & needed) == needed ?
	                 DXGI_FORMAT_R11G11B10_FLOAT : DXGI_FORMAT_R16G16B16A16_FLOAT;

	for (UINT level = 0; level < LEVEL_COUNT; ++level)
	{
		if (occupancy[level].Create(device, DXGI_FORMAT_R32_FLOAT) == false ||
		    radiance[0][level].Create(device, radianceFormat) == false || radiance[1][level].Create(device, radianceFormat) == false)
		{
			Utilities::Log::Write("voxel reflections: failed to create the voxel volumes (%u^3, level %u)", RESOLUTION, level);
			return false;
		}
	}

	/* Zero-initialised: every level starts invalid, so the first carve pass clears the volumes */
	D3D11_BUFFER_DESC desc = {};
	desc.ByteWidth = STATE_ELEMENTS * 16;
	desc.Usage = D3D11_USAGE_DEFAULT;
	desc.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
	desc.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;
	desc.StructureByteStride = 16;
	int32_t zeros[STATE_ELEMENTS * 4] = {};
	D3D11_SUBRESOURCE_DATA data = {};
	data.pSysMem = zeros;
	if (FAILED(device->CreateBuffer(&desc, &data, &state)) || FAILED(device->CreateShaderResourceView(state, nullptr, &stateSrv)) ||
	    FAILED(device->CreateUnorderedAccessView(state, nullptr, &stateUav)))
	{
		Utilities::Log::Write("voxel reflections: failed to create the state buffer");
		return false;
	}

	const float radianceBytes = radianceFormat == DXGI_FORMAT_R11G11B10_FLOAT ? 4.0f : 8.0f;
	const float megabytes = LEVEL_COUNT * RESOLUTION * RESOLUTION * RESOLUTION * (4.0f + 2.0f * radianceBytes) / (1024.0f * 1024.0f);
	Utilities::Log::Write("voxel reflections: %u levels of %u^3 voxels ready (%.0f MB, radiance %s)", LEVEL_COUNT, RESOLUTION, megabytes,
	                      radianceFormat == DXGI_FORMAT_R11G11B10_FLOAT ? "R11G11B10F" : "RGBA16F");
	return true;
}

/* The shaders write here; the result is copied into the SSR target, so the engine's render target binding is never touched */
bool VoxelReflections::EnsureOutput(ID3D11Device* device, UINT width, UINT height)
{
	if (output && outputWidth == width && outputHeight == height)
		return true;
	Utilities::SafeRelease(outputUav);
	Utilities::SafeRelease(output);
	outputWidth = outputHeight = 0;

	D3D11_TEXTURE2D_DESC desc = {};
	desc.Width = width;
	desc.Height = height;
	desc.MipLevels = 1;
	desc.ArraySize = 1;
	desc.SampleDesc.Count = 1;
	desc.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
	desc.Usage = D3D11_USAGE_DEFAULT;
	desc.BindFlags = D3D11_BIND_UNORDERED_ACCESS;
	if (FAILED(device->CreateTexture2D(&desc, nullptr, &output)) || FAILED(device->CreateUnorderedAccessView(output, nullptr, &outputUav)))
	{
		Utilities::SafeRelease(outputUav);
		Utilities::SafeRelease(output);
		Utilities::Log::Write("voxel reflections: failed to create a %ux%u output texture", width, height);
		return false;
	}
	outputWidth = width;
	outputHeight = height;
	return true;
}




/* Creates what the mode needs and fills the constant buffer */
bool VoxelReflections::Prepare(ID3D11DeviceContext* context, const SsrDraw& draw, int mode, bool needVolumes)
{
	const UINT width = static_cast<UINT>(draw.viewport.Width);
	const UINT height = static_cast<UINT>(draw.viewport.Height);

	ID3D11Device* device = nullptr;
	context->GetDevice(&device);
	if (device == nullptr)
		return false;
	if (initTried == false)
		ready = Initialize(device);
	if (ready && needVolumes && volumesTried == false)
		volumesReady = CreateVolumes(device);
	const bool ok = ready && (needVolumes == false || volumesReady) && EnsureOutput(device, width, height);
	device->Release();
	if (ok == false)
		return false;

	/* A new voxel size changes the meaning of every stored cell */
	const float size = voxelSize >= 2.0f && voxelSize <= 100.0f ? voxelSize : 8.0f;
	if (size != appliedVoxelSize)
	{
		if (appliedVoxelSize != 0.0f)
			Utilities::Log::Write("voxel reflections: voxel size %.1f cm (levels up to %.1f cm, cache radius %.1f m)", size,
			                      size * (1 << (LEVEL_COUNT - 1)), size * (1 << (LEVEL_COUNT - 1)) * RESOLUTION * 0.5f / 100.0f);
		appliedVoxelSize = size;
		resetPending = true;
	}

	D3D11_MAPPED_SUBRESOURCE mapped;
	if (FAILED(context->Map(constants, 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped)))
		return false;
	Constants c = {};
	c.offset[0] = static_cast<uint32_t>(draw.viewport.TopLeftX);
	c.offset[1] = static_cast<uint32_t>(draw.viewport.TopLeftY);
	c.size[0] = width;
	c.size[1] = height;
	c.mode = static_cast<uint32_t>(mode);
	c.scale = debugScale > 0.0f ? debugScale : 16.0f;
	c.resolution = RESOLUTION;
	c.reset = (needVolumes && resetPending) ? 1u : 0u;
	c.voxelSize0 = size;
	c.maxRoughness = maxRoughness > 0.0f ? (maxRoughness < 1.0f ? maxRoughness : 1.0f) : 0.6f;
	c.maxDistance = maxDistance > 100.0f ? maxDistance : 3000.0f;
	c.carveRate = CARVE_RATE;
	c.frame = frameIndex;
	memcpy(mapped.pData, &c, sizeof(c));
	context->Unmap(constants, 0);

	if (needVolumes)
		resetPending = false;
	return true;
}

void VoxelReflections::UnbindAll(ID3D11DeviceContext* context)
{
	Utilities::ComputeState::Unbind(context);
}

void VoxelReflections::Finish(ID3D11DeviceContext* context, const SsrDraw& draw)
{
	const UINT width = static_cast<UINT>(draw.viewport.Width);
	const UINT height = static_cast<UINT>(draw.viewport.Height);
	D3D11_BOX box = { 0, 0, 0, width, height, 1 };
	context->CopySubresourceRegion(draw.target, 0, static_cast<UINT>(draw.viewport.TopLeftX), static_cast<UINT>(draw.viewport.TopLeftY), 0,
	                               output, 0, &box);
}

bool VoxelReflections::RunDebug(ID3D11DeviceContext* context, const SsrDraw& draw, int mode)
{
	if (Prepare(context, draw, mode, false) == false)
		return false;
	const UINT width = static_cast<UINT>(draw.viewport.Width);
	const UINT height = static_cast<UINT>(draw.viewport.Height);

	ID3D11ShaderResourceView* inputs[3] = { draw.srvs[SLOT_DEPTH], draw.srvs[SLOT_GBUFFER_A], draw.srvs[SLOT_GBUFFER_B] };
	ID3D11Buffer* buffers[2] = { constants, draw.view };   // A missing View buffer only breaks the world grid (mode 5)

	savedState.Save(context);
	UnbindAll(context);
	context->CSSetShader(debugShader, nullptr, 0);
	context->CSSetConstantBuffers(0, 2, buffers);
	context->CSSetShaderResources(0, _countof(inputs), inputs);
	context->CSSetUnorderedAccessViews(0, 1, &outputUav, nullptr);
	context->Dispatch((width + 7) / 8, (height + 7) / 8, 1);
	UnbindAll(context);
	savedState.Restore(context);

	Finish(context, draw);
	return true;
}

bool VoxelReflections::RunVoxels(ID3D11DeviceContext* context, const SsrDraw& draw, int mode)
{
	if (draw.view == nullptr)
	{
		static bool logged = false;
		if (logged == false)
		{
			logged = true;
			Utilities::Log::Write("voxel reflections: no constant buffer in slot %d of the SSR pass (r.VoxelReflections.ViewBufferSlot)", viewBufferSlot);
		}
		return false;
	}
	if (Prepare(context, draw, mode, true) == false)
		return false;
	const UINT width = static_cast<UINT>(draw.viewport.Width);
	const UINT height = static_cast<UINT>(draw.viewport.Height);

	ID3D11Buffer* buffers[2] = { constants, draw.view };
	/* Last frame's radiance is read, this frame's is written (D3D11 cannot load from a typed R11G11B10 UAV) */
	Volume* previousRadiance = radiance[historyIndex];
	Volume* currentRadiance = radiance[historyIndex ^ 1];
	ID3D11UnorderedAccessView* volumeUavs[LEVEL_COUNT * 2] = {};
	ID3D11ShaderResourceView* previousSrvs[LEVEL_COUNT] = {};
	ID3D11ShaderResourceView* currentSrvs[LEVEL_COUNT] = {};
	ID3D11ShaderResourceView* occupancySrvs[LEVEL_COUNT] = {};
	for (UINT level = 0; level < LEVEL_COUNT; ++level)
	{
		volumeUavs[level] = occupancy[level].uav;
		volumeUavs[LEVEL_COUNT + level] = currentRadiance[level].uav;
		previousSrvs[level] = previousRadiance[level].srv;
		currentSrvs[level] = currentRadiance[level].srv;
		occupancySrvs[level] = occupancy[level].srv;
	}

	savedState.Save(context);
	UnbindAll(context);
	context->CSSetConstantBuffers(0, 2, buffers);

	/* 1. Move the windows */
	context->CSSetShader(updateShader, nullptr, 0);
	context->CSSetUnorderedAccessViews(0, 1, &stateUav, nullptr);
	context->Dispatch(1, 1, 1);
	UnbindAll(context);

	/* 2. Copy last frame's radiance, clear scrolled-in voxels, fade voxels the camera sees through */
	context->CSSetShader(carveShader, nullptr, 0);
	context->CSSetShaderResources(SLOT_DEPTH, 1, &draw.srvs[SLOT_DEPTH]);
	context->CSSetShaderResources(4, LEVEL_COUNT, previousSrvs);
	context->CSSetShaderResources(8, 1, &stateSrv);
	context->CSSetUnorderedAccessViews(0, _countof(volumeUavs), volumeUavs, nullptr);
	context->Dispatch(RESOLUTION / 4, RESOLUTION / 4, RESOLUTION * LEVEL_COUNT / 4);

	/* 3. Blend in visible surfaces (one pixel of every 2x2 block, rotating) */
	context->CSSetShader(injectShader, nullptr, 0);
	context->CSSetShaderResources(3, 1, &draw.srvs[SLOT_SCENE_COLOR]);
	context->Dispatch((width / 2 + 8) / 8, (height / 2 + 8) / 8, 1);
	UnbindAll(context);

	/* 4. Trace */
	ID3D11ShaderResourceView* gbuffer[3] = { draw.srvs[SLOT_DEPTH], draw.srvs[SLOT_GBUFFER_A], draw.srvs[SLOT_GBUFFER_B] };
	context->CSSetShader(traceShader, nullptr, 0);
	context->CSSetShaderResources(0, _countof(gbuffer), gbuffer);
	context->CSSetShaderResources(4, LEVEL_COUNT, currentSrvs);
	context->CSSetShaderResources(8, 1, &stateSrv);
	context->CSSetShaderResources(9, LEVEL_COUNT, occupancySrvs);
	context->CSSetSamplers(0, 1, &linearWrap);
	context->CSSetUnorderedAccessViews(0, 1, &outputUav, nullptr);
	context->Dispatch((width + 7) / 8, (height + 7) / 8, 1);
	UnbindAll(context);

	savedState.Restore(context);
	Finish(context, draw);
	historyIndex ^= 1;

	static bool logged = false;
	if (logged == false)
	{
		logged = true;
		Utilities::Log::Write("voxel reflections: running (%u levels of %u^3, %.1f cm .. %.1f cm voxels, view buffer slot %d)", LEVEL_COUNT,
		                      RESOLUTION, appliedVoxelSize, appliedVoxelSize * (1 << (LEVEL_COUNT - 1)), viewBufferSlot);
	}
	return true;
}




bool VoxelReflections::OnDrawIndexed(ID3D11DeviceContext* context, UINT numPrimitives, UINT numInstances)
{
	/* The SSR pass is a single full-screen triangle; only the main view is handled */
	if (enable == 0 || context == nullptr || foundThisFrame || numPrimitives > 2 || numInstances > 1)
		return false;

	SsrDraw draw;
	if (Match(context, draw) == false)
	{
		draw.Release();
		return false;
	}
	foundThisFrame = true;

	/* 0 = voxel reflections, 1..5 = G-buffer / camera debug views, 6 = voxel cache view */
	static int loggedMode = -1;
	const int mode = (debug >= 0 && debug <= MAX_MODE) ? debug : 0;
	if (mode != loggedMode)
	{
		static const char* names[] = { "voxel reflections", "magenta", "GBuffer normals", "depth bands", "roughness", "world grid (1 m)",
		                               "voxel cache view" };
		Utilities::Log::Write("voxel reflections: SSR output = %s", names[mode]);
		if (debug != mode)
			Utilities::Log::Write("voxel reflections: r.VoxelReflections.Debug %d is not supported (0 = off, 1..6 = debug views)", debug);
		loggedMode = mode;
	}

	const bool debugView = mode >= 1 && mode <= 5;
	if (debugView)
		resetPending = true;   // The cache is not updated during debug views
	const bool replaced = debugView ? RunDebug(context, draw, mode) : RunVoxels(context, draw, mode);
	static bool failureLogged = false;
	if (replaced == false && failureLogged == false)
	{
		failureLogged = true;
		Utilities::Log::Write("voxel reflections: pass failed (mode %d), the engine SSR is used", mode);
	}
	draw.Release();
	return replaced;
}

void VoxelReflections::OnPresent()
{
	++frameIndex;
	if (enable == 0)
	{
		foundThisFrame = false;
		framesWithoutSsr = 0;
		resetPending = true;   // The cache stops following the scene while off
		return;
	}

	/* Long gaps (menus, loading screens) make the cache stale */
	framesWithoutSsr = foundThisFrame ? 0 : framesWithoutSsr + 1;
	foundThisFrame = false;
	if (framesWithoutSsr == 30)
		resetPending = true;

	if (framesWithoutSsr == 240 && warnedMissing == false)
	{
		warnedMissing = true;
		Utilities::Log::Write("voxel reflections: no SSR draw in the last 240 frames - SSR has to be on (r.SSR.Quality 1..4); "
		                      "menus and loading screens have none");
	}
}
